"""The one line every generated file with comment syntax starts with (ADR 0015 "The generated header"): the target
package, its version and the api, never a timestamp, a path or a hash. JSON has no comment syntax and the manifest
covers it."""

import re
from typing import Final

from seampact.ir.write.generated_file import GeneratedFile
from seampact.ir.write.refusal import WriterRefusal

_NO_COMMENT: Final = ""
# The extensions the Python targets emit, each with the line comment that carries the header.
_LINE_COMMENT_BY_EXTENSION: Final = {".py": "#", ".pyi": "#", ".yaml": "#", ".toml": "#", ".json": _NO_COMMENT}
# A control character ends the comment line.
_UNSAFE_HEADER_VALUE: Final = re.compile(r"[\x00-\x1f\x7f]")
_REPORT_FIX: Final = (
    "Report this to the target's maintainers: the writer must learn the extension before a target emits it."
)


def header_line(generator: str, version: str, api: str) -> str:
    return f'Generated by {generator} {version} from api "{api}". Do not edit.'


def add_header(
    files: list[GeneratedFile], generator: str, version: str, api: str
) -> list[GeneratedFile] | list[WriterRefusal]:
    """Each file with the header added, or one refusal per file the writer cannot head."""
    for name, value in (("package", generator), ("version", version), ("api", api)):
        if _UNSAFE_HEADER_VALUE.search(value):
            return [
                WriterRefusal(
                    "file.header.unsafe",
                    f"The {name} {value!r} holds a control character, which would break the generated header line.",
                    f"Correct the {name} in the target's metadata or in the contract, then run again.",
                )
            ]

    line = header_line(generator, version, api)
    finished: list[GeneratedFile] = []
    refusals: list[WriterRefusal] = []

    for file in files:
        headed = _headed(file, line)

        if isinstance(headed, WriterRefusal):
            refusals.append(headed)
        else:
            finished.append(headed)

    return refusals or finished


def _headed(file: GeneratedFile, line: str) -> GeneratedFile | WriterRefusal:
    extension = _extension_of(file.path)
    comment = _LINE_COMMENT_BY_EXTENSION.get(extension)

    if comment is None:
        known = ", ".join(_LINE_COMMENT_BY_EXTENSION)

        return WriterRefusal(
            "file.extension.unsupported",
            f"The target generated '{file.path}', whose extension is not one the writer knows ({known}).",
            _REPORT_FIX,
        )

    if comment == _NO_COMMENT:
        return file

    return GeneratedFile(file.path, f"{comment} {line}\n{file.contents}")


def _extension_of(path: str) -> str:
    file_name = path.rsplit("/", 1)[-1]
    dot = file_name.rfind(".")

    return "" if dot <= 0 else file_name[dot:]
